export const defaults = {input:2000,cached:0,output:350,calls:1,volume:10000,retries:1,toolCalls:1,toolCost:0.005,escalate:100,humanCost:4,humanSuccess:100};
export const limits={input:[0,1e9],cached:[0,1e9],output:[0,1e9],calls:[1,10000],volume:[0,1e9],retries:[0,10],toolCalls:[0,10000],toolCost:[0,1e6],escalate:[0,100],humanCost:[0,1e6],humanSuccess:[0,100]};
export function validate(s,models){const errors=[];for(const [k,[min,max]] of Object.entries(limits)){if(!Number.isFinite(s[k])||s[k]<min||s[k]>max)errors.push(`${k} must be between ${min} and ${max}`);}for(const k of ['input','cached','output','calls','volume','retries'])if(!Number.isInteger(s[k]))errors.push(`${k} must be a whole number`);if(s.cached>s.input)errors.push('Cached tokens cannot exceed total input tokens');for(const m of models)for(const k of ['input','cached','output','success'])if(!Number.isFinite(m[k])||m[k]<0||m[k]>(k==='success'?100:1e6))errors.push(`${m.name}: check ${k}`);return errors;}
export function calculate(s,m,costs){const perCall=((s.input-s.cached)*m.input+s.cached*m.cached+s.output*m.output)/1e6;const perAttempt=perCall*s.calls;const p=m.success/100;const attempts=Array.from({length:s.retries+1},(_,i)=>(1-p)**i).reduce((a,b)=>a+b,0);const failed=(1-p)**(s.retries+1);const aiSuccess=1-failed;const escalation=failed*s.escalate/100;const finalSuccess=aiSuccess+escalation*s.humanSuccess/100;const api=perAttempt*attempts;const tools=s.toolCalls*s.toolCost*attempts;const human=escalation*s.humanCost;const total=api+tools+human;const result={perCall,perAttempt,apiMonthly:perAttempt*s.volume,attempts,aiSuccess,escalation,finalSuccess,api,tools,human,total,workflowMonthly:total*s.volume,successes:finalSuccess*s.volume,costPerSuccess:finalSuccess>0&&s.volume>0?total/finalSuccess:null};result.costs=calculateCosts(s,result,costs);return result;}
// Additional costs are USD amounts, never inferred vendor prices. Missing is not zero.
export const costFields=[
['setupParsing','Prepare and clean documents (one-time)','setup'],['setupEmbeddings','Make documents searchable (one-time)','setup'],['setupIndexing','Set up and connect search (one-time)','setup'],
['queryEmbeddings','Prepare each question for search / attempt','variable'],['retrieval','Find matching information / attempt','variable'],['reranking','Reorder search results / attempt','variable'],['dataTransfer','Data transfer / attempt','variable'],['otherUsage','Other usage fees / attempt','variable'],
['vectorStorage','Keep information available / month','fixed'],['compute','Run the service / month','fixed'],['monitoring','Check service health / month','fixed'],['maintenance','Support and upkeep / month','fixed']];
export function validateCosts(c){if(c===undefined)return [];if(!c||typeof c!=='object'||Array.isArray(c))return ['Additional costs must be an object'];const errors=[];const keys=[...costFields.map(f=>f[0]),'amortizationMonths','allocatedSharePercent'];for(const k of Object.keys(c)){if(!keys.includes(k)){errors.push('Unknown additional cost field');continue;}const v=c[k];if(v===null)continue;const min=k==='amortizationMonths'?1:0,max=k==='amortizationMonths'?1200:k==='allocatedSharePercent'?100:1e9;if(!Number.isFinite(v)||v<min||v>max||(k==='amortizationMonths'&&!Number.isInteger(v)))errors.push(k+' is outside its allowed range');}return errors;}
export function calculateCosts(s,r,c={}){const errors=validateCosts(c);if(errors.length)throw Error(errors.join('; '));const missing=costFields.filter(([k])=>c[k]===undefined||c[k]===null).map(([k])=>k);const sum=group=>costFields.filter(f=>f[2]===group).reduce((n,[k])=>n+(c[k]??0),0);const setup=sum('setup'),fixed=sum('fixed'),variablePerAttempt=sum('variable');const months=c.amortizationMonths??12,share=c.allocatedSharePercent??100;const setupMonthly=setup/months*share/100,fixedMonthly=fixed*share/100,variableMonthly=variablePerAttempt*r.attempts*s.volume;const knownMonthly=r.workflowMonthly+setupMonthly+fixedMonthly+variableMonthly;const complete=missing.length===0;return {complete,missing_cost_fields:missing,status:complete?'entered_scope_complete':'partial_missing_costs',assumptions:{amortization_months:months,allocated_share_percent:share,variable_frequency:'per complete attempt; repeats on retry',allocation_scope:'setup and fixed monthly budgets only; variable and human costs already belong to this workload'},setup_total_before_allocation:setup,setup_monthly_allocated:setupMonthly,fixed_monthly_allocated:fixedMonthly,variable_per_attempt:variablePerAttempt,variable_monthly:variableMonthly,known_monthly_usd:knownMonthly,known_cost_per_task_usd:s.volume>0?knownMonthly/s.volume:null,known_cost_per_resolved_task_usd:r.successes>0?knownMonthly/r.successes:null,full_monthly_usd:complete?knownMonthly:null,fully_loaded_cost_per_resolved_task_usd:complete&&r.successes>0?knownMonthly/r.successes:null,scope_note:'Complete only for entered categories and stated assumptions; not a guarantee that every business expense is covered. Do not double count fees already included in model/tool prices or another budget.'};}
